def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    players_alive = 1 + len(alive_opponents)
    affordable_cap = min(budget, DAILY_SALARY)

    prev_bids = []
    urgent_opponents = 0
    rich_opponents = 0
    for opp in alive_opponents:
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opponents += 1
        if opp.get('budget', 0) >= DAILY_SALARY * 2:
            rich_opponents += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None and prev.get('error') in (None, '', False):
            prev_bids.append(prev.get('bid', 0))

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    supply_ratio = supply / float(WATER_REQ * players_alive)

    if hp <= 2 or no_water >= 2:
        base = DAILY_SALARY * 0.96
    elif hp <= 4 or no_water >= 1:
        base = DAILY_SALARY * 0.82
    else:
        if supply_ratio >= 1.2:
            base = DAILY_SALARY * 0.28
        elif supply_ratio >= 0.9:
            base = DAILY_SALARY * 0.48
        elif supply_ratio >= 0.7:
            base = DAILY_SALARY * 0.64
        else:
            base = DAILY_SALARY * 0.78

    pressure = 0
    if highest_prev > 0:
        if highest_prev >= DAILY_SALARY * 0.9:
            pressure += 8
        elif highest_prev >= DAILY_SALARY * 0.7:
            pressure += 5
        elif highest_prev >= DAILY_SALARY * 0.5:
            pressure += 2
    pressure += urgent_opponents * 2
    pressure += rich_opponents * 1

    target = base + pressure

    if highest_prev > 0 and (hp <= 4 or supply_ratio < 0.9):
        target = max(target, highest_prev + 1.5)
    elif avg_prev > 0 and supply_ratio < 0.7:
        target = max(target, avg_prev + 2)

    if players_alive <= 2 and hp > 4 and no_water == 0:
        target *= 0.9

    reserve_floor = 0
    if hp > 4 and no_water == 0:
        reserve_floor = DAILY_SALARY * 0.18

    bid = min(affordable_cap, max(reserve_floor, target))

    if budget < DAILY_SALARY * 0.75 and hp > 3 and no_water == 0:
        bid = min(bid, budget * 0.55)

    if bid < 0:
        bid = 0
    if bid > budget:
        bid = budget
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25

    supply = day_context.get('supply', float(MAX_SUPPLY))
    day = day_context.get('day', 0)

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append(o)

    if not alive_opponents:
        return min(my_status.get('budget', 0), DAILY_SALARY * 0.4)

    # Read yesterday bids (immediate reaction)
    prev_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            prev_bids.append(b)

    # If we have no signal, bid moderately; later days bid more.
    if not prev_bids:
        hp = my_status.get('hp', 0)
        budget = my_status.get('budget', 0)
        base = DAILY_SALARY * (0.45 if day <= 5 else 0.6)
        if hp <= 2:
            base = DAILY_SALARY * 0.85
        return min(budget, base)

    highest_prev_bid = max(prev_bids)
    avg_prev_bid = sum(prev_bids) / float(len(prev_bids))

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0)
    no_water_days = my_status.get('no_water_days', 0)

    # Estimate how much water is needed this day.
    # Target: secure at least WATER_REQ unless budget/HP is critical.
    # Convert supply to a rough scarcity factor.
    # Note: avoid float indices; no indexing used here.
    scarcity = 0.0
    if MAX_SUPPLY > 0:
        scarcity = (float(MAX_SUPPLY) - float(supply)) / float(MAX_SUPPLY)

    # Base bid logic driven by opponent pressure.
    # If opponents bid very high yesterday, they are likely competing hard today.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Match pressure but keep a budget-aware cap.
        if hp <= 2 or no_water_days >= 1:
            target = DAILY_SALARY * 0.95
        else:
            target = DAILY_SALARY * (0.75 + 0.1 * scarcity)
    elif avg_prev_bid >= DAILY_SALARY * 0.55:
        target = max(highest_prev_bid + 1.0, DAILY_SALARY * (0.55 + 0.15 * scarcity))
    else:
        # Low yesterday bids: bid just enough to outcompete while conserving.
        target = max(DAILY_SALARY * (0.45 + 0.2 * scarcity), avg_prev_bid + 2.0)

    # Ensure we don't overbid beyond budget.
    # Also, if our HP is low, increase aggressiveness.
    if hp <= 1:
        target = max(target, DAILY_SALARY * 0.9)
    elif hp <= 3:
        target = max(target, DAILY_SALARY * 0.65)

    # Final clamp to budget.
    bid = min(budget, target)

    # If supply is extremely low, add a small urgency bump.
    if float(supply) <= float(WATER_REQ):
        bid = min(budget, max(bid, DAILY_SALARY * 0.8))

    # Never negative.
    if bid < 0:
        bid = 0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Get yesterday's bids from opponents (if available)
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Base bid on my need and opponent aggression
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        # If someone bid very high, be conservative if I can survive
        if highest_prev >= DAILY_SALARY * 0.8:
            if hp > 3:
                return min(budget, DAILY_SALARY * 0.3)
            else:
                return min(budget, DAILY_SALARY * 0.9)
        else:
            # Try to outbid the highest by a small margin
            target = max(DAILY_SALARY * 0.5, highest_prev + 2)
            return min(budget, target)
    else:
        # No trace: bid based on supply and HP
        if hp <= 2:
            return min(budget, DAILY_SALARY * 0.9)
        else:
            # Moderate bid proportional to scarcity
            scarcity_factor = 1.0 - (supply - 15) / (25 - 15)
            bid = DAILY_SALARY * (0.3 + 0.4 * scarcity_factor)
            return min(budget, bid)
